4	#[cfg(test)]
5	mod tests {
6	    use std::path::Path;
7	
8	    use anyhow::Result;
9	    use ruff_python_ast::PythonVersion;
10	    use test_case::test_case;
11	
12	    use crate::assert_diagnostics;
13	    use crate::registry::Rule;
14	    use crate::settings::LinterSettings;
15	    use crate::settings::types::PreviewMode;
16	    use crate::test::test_path;
17	
18	    #[test_case(Rule::UnnecessaryListCast, Path::new("PERF101.py"))]
19	    #[test_case(Rule::IncorrectDictIterator, Path::new("PERF102.py"))]
20	    #[test_case(Rule::TryExceptInLoop, Path::new("PERF203.py"))]
21	    #[test_case(Rule::ManualListComprehension, Path::new("PERF401.py"))]
22	    #[test_case(Rule::ManualListCopy, Path::new("PERF402.py"))]
23	    #[test_case(Rule::ManualDictComprehension, Path::new("PERF403.py"))]
24	    fn rules(rule_code: Rule, path: &Path) -> Result<()> {
25	        let snapshot = format!("{}_{}", rule_code.noqa_code(), path.to_string_lossy());
26	        let diagnostics = test_path(
27	            Path::new("perflint").join(path).as_path(),
28	            &LinterSettings::for_rule(rule_code).with_target_version(PythonVersion::PY310),
29	        )?;
30	        assert_diagnostics!(snapshot, diagnostics);
31	        Ok(())
32	    }
33	
34	    // TODO: remove this test case when the fixes for `perf401` and `perf403` are stabilized
35	    #[test_case(Rule::ManualDictComprehension, Path::new("PERF403.py"))]
36	    #[test_case(Rule::ManualListComprehension, Path::new("PERF401.py"))]
37	    fn preview_rules(rule_code: Rule, path: &Path) -> Result<()> {
38	        let snapshot = format!(
39	            "preview__{}_{}",
40	            rule_code.noqa_code(),
41	            path.to_string_lossy()
42	        );
43	        let diagnostics = test_path(
44	            Path::new("perflint").join(path).as_path(),
45	            &LinterSettings {
46	                preview: PreviewMode::Enabled,
47	                unresolved_target_version: PythonVersion::PY310.into(),
48	                ..LinterSettings::for_rule(rule_code)
49	            },
50	        )?;
51	        assert_diagnostics!(snapshot, diagnostics);
52	        Ok(())
53	    }
54	}
